foreach($e in $freeze.entries){$p=[string]$e.path;$h=(Get-FileHash $p -Algorithm SHA256).Hash.ToUpperInvariant();$rows += [ordered]@{path=$p;bytes=(Get-Item $p).Length;sha256=$h;matchesFreeze=($h -eq [string]$e.sha256)}}
