$out=Join-Path $base 'png-final-validation-summary.json';if(Test-Path $out){throw 'Refusing to overwrite final PNG summary'};[IO.File]::WriteAllText($out,($report|ConvertTo-Json -Depth 10),[Text.UTF8Encoding]::new($false));$compact=[ordered]@{freezeInputs=$rows.Count;freezeAllMatch=$report.freezeAllMatch;sourceArchiveSHA256=$sourceHash;packageArchiveSHA256=$package.archiveSHA256;packageMembers=$package.memberCount;payloads=$package.payloadCount;releaseTests=$consumer.releaseTests;debugTests=$consumer.debugTests;guards=$guards.Count;outsideAbsent=$report.outsideOutputStillAbsent;headerNormalizedExact=$report.prebuiltHeader.normalizedTextExact;libraryBytes=$report.library.bytes;librarySHA256=$report.library.sha256;summary=$out};Write-Output ($compact|ConvertTo-Json -Compress -Depth 5)
